"Каждый осколок Алатыря, найденный любым Ловчим, — в разломах и у хранителей-старейшин Капищ, — ложится в общий камень Ордена. Собрана грань — дорога в её мир распутана: {0} дня духи этой мифологии встречаются в {1} раза чаще, у всех Ловчих разом. Собраны все грани сезона — приходит Кощей: {2} дней он ждёт во всех Разломах мира, а потом раскалывает камень. Из трещины выходит новая мифология, начинается новый сезон — и в Лиге тоже. В новом сезоне у камня на одну грань больше.":"Herhangi bir Avcı'nın bulduğu her Alatyr parçası — yarıklarda ve Kapishche'lerin yaşlı bekçilerinde — Tarikat'ın ortak taşına eklenir. Bir yüz toplanınca o dünyanın yolu çözülür: {0} gün boyunca o mitolojinin ruhları tüm Avcılar için aynı anda {1} kat daha sık görünür. Sezonun tüm yüzleri toplanınca Koschei gelir: {2} gün boyunca dünyadaki tüm Yarıklarda bekler, sonra taşı parçalar. Çatlaktan yeni bir mitoloji çıkar ve yeni bir sezon başlar — Lig'de de. Yeni sezonda taşın bir yüzü daha fazladır.",
