"ур. {0}":"sv. {0}",
"Здесь пока тихо":"Burası şimdilik sessiz",
"Напиши первым — тебя увидят все Ловчие твоего клана.":"İlk sen yaz — klanındaki tüm Avcılar görecek.",
"Напиши первым — тебя увидят все Ловчие Ордена.":"İlk sen yaz — Tarikat'ın tüm Avcıları görecek.",
"Новые сообщения: {0}":"Yeni mesajlar: {0}",
"Пожаловаться?":"Şikâyet edilsin mi?",
"На сообщение Ловчего «{0}». После трёх жалоб от разных Ловчих оно скрывается для всех.":"“{0}” adlı Avcının mesajı şikâyet edilecek. Farklı Avcılardan üç şikâyet gelince mesaj herkesten gizlenir.",
"Пожаловаться":"Şikâyet et",
"Жалоба отправлена — спасибо":"Şikâyet gönderildi — teşekkürler",
"Скрыть сообщения?":"Mesajlar gizlensin mi?",
"Сообщения Ловчего «{0}» перестанут показываться на этом телефоне. Вернуть можно в любой момент — строкой «Скрытых Ловчих» вверху чата.":"“{0}” adlı Avcının mesajları bu telefonda artık görünmeyecek. İstediğin an geri getirebilirsin — sohbetin üstündeki “Gizlenen Avcılar” satırından.",
"Скрыть":"Gizle",
"Скрыто. Вернуть — «Скрытых Ловчих» вверху чата":"Gizlendi. Geri getirmek için: sohbetin üstündeki “Gizlenen Avcılar”",
"твой клан":"senin klanın",
"Клан «?»":"“?” Klanı",
"откроется в сезоне {0}":"{0}. sezonda açılacak",
"Клан мифологии следующего сезона. Он откроется, когда Орден соберёт Алатырь-камень и Кощей снова расколет его.":"Gelecek sezonun mitolojisinin klanı. Tarikat Alatyr taşını topladığında ve Koschei onu yeniden kırdığında açılacak.",
"Клан можно выбрать с {0} уровня":"Klan seçimi {0}. seviyeden itibaren",
"Выбери клан":"Klanını seç",
"У каждой мифологии Перепутицы — свой клан Ордена. Кланы держат Капища: поставь своего духа защитником — и Капище окрасится цветом твоего клана, а тебе каждый день будет приходить дань. Выбор — навсегда.":"Büyük Düğüm'ün her mitolojisinin Tarikat'ta kendi klanı var. Klanlar Kapishche'leri tutar: ruhunu savunucu olarak yerleştir — Kapishche klanının rengine bürünsün, sana da her gün haraç gelsin. Seçim kalıcıdır.",
"Позже":"Sonra",
"Выбор — навсегда: сменить клан потом нельзя.":"Seçim kalıcıdır: klanını sonradan değiştiremezsin.",
"Переход бесплатный и единственный. Защитники достоят свой срок на Капищах прежнего клана, чат — уже нового.":"Geçiş ücretsizdir ve yalnızca bir kez yapılır. Savunucuların eski klanın Kapishche'lerindeki nöbetlerini tamamlar; sohbet ise artık yeni klanınki olur.",
"Мифология: {0}":"Mitoloji: {0}",
"Звание: {0}":"Unvan: {0}",
"На святилищах своей мифологии ({0}) защитники клана собирают дань {1}.":"Kendi mitolojisinin tapınaklarında ({0}) klanın savunucuları {1} haraç toplar.",
"Перейти":"Geç",
"Вступить":"Katıl",
"Ты в «{0}»! Побеждай на Капищах и ставь защитников.":"Artık “{0}” klanındasın! Kapishche'lerde kazan ve savunucu koy.",
"Теперь ты в «{0}». Добро пожаловать, {1}!":"Artık “{0}” içindesin. Hoş geldin, {1}!",
"Дружины стали кланами":"Drujinalar klan oldu",
"Орден собрал Ловчих всех земель: теперь у каждой мифологии свой клан, а с каждым новым сезоном Алатыря приходит ещё один.":"Tarikat her diyardan Avcıları bir araya getirdi: artık her mitolojinin kendi klanı var ve her yeni Alatyr sezonu bir klan daha getiriyor.",
"Твоя дружина теперь —":"Drujinan artık",
"Защитники на Капищах и чат клана остались с тобой.":"Kapishche'lerdeki savunucuların ve klan sohbeti seninle kalıyor.",
"Один раз можно бесплатно перейти в любой открытый клан. Выбери его — или останься. Перейти можно и позже, на экране клана.":"Bir kereye mahsus, açık olan herhangi bir klana ücretsiz geçebilirsin. Birini seç — ya da kal. Daha sonra klan ekranından da geçebilirsin.",
"Остаться":"Kal",
"Кого поставить защитником?":"Kimi savunucu yapacaksın?",
"Дух останется у тебя: на Капище встанет его отражение. Пока он стоит, раз в день приходит дань — ✦ {0} и оберег.":"Ruh sende kalır: Kapishche'de onun yansıması durur. O orada durdukça günde bir kez haraç gelir — ✦ {0} ve bir tılsım.",
"Отражение стоит до {0} суток: первые {1} ч в полной силе, потом устаёт и слабеет, а затем возвращается домой. Защитники — не больше чем на {2} Капищах.":"Savunma en çok {0} gün sürer: ilk {1} sa tam güçte, sonra yorulur ve zayıflar, ardından eve döner. Savunucular en çok {2} Kapishche'de olabilir.",
"Это святилище мифологии твоего клана — дань здесь {0}.":"Burası klanının mitolojisine ait bir tapınak — burada haraç {0}.",
"Защитник встал на Капище «{0}» — оно под знаменем «{1}»":"Savunucu “{0}” Kapishche'sine yerleşti — artık “{1}” sancağı altında",
"Срок на посту вышел — защитники вернулись с {0}. За службу: {1}":"Görev süresi doldu — savunucular şuradan döndü: {0}. Hizmet karşılığı: {1}",
"Защитники вернулись с {0}: соперники победили. За службу: {1}":"Savunucular şuradan döndü: {0} — rakipler kazandı. Hizmet karşılığı: {1}",
"Защитник вернулся с {0}: соперники победили. За службу: {1}":"Savunucu şuradan döndü: {0} — rakipler kazandı. Hizmet karşılığı: {1}",
