"Пока нигде. Победи на Капище и поставь защитника — каждый день будет приходить дань.":"Henüz hiçbir yerde. Bir Kapishche'de kazan ve savunucu koy — her gün haraç gelir.",
"Дань — ✦ {0}, оберег и {1} {2} в день за каждое Капище, где твой защитник отстоял хотя бы {3} ч. Защитник стоит до {4} суток и понемногу устаёт; если соперники его победят или срок выйдет, он вернётся с искрами за время на посту. Часть Капищ — вольные: их не держит ни один клан.":"Haraç — savunucunun en az {3} sa durduğu her Kapishche için günde ✦ {0}, tılsım ve {1} {2}. Savunucu en çok {4} gün durur ve yavaş yavaş yorulur; rakipler onu yenerse ya da süre dolarsa görev süresine göre kıvılcımla döner. Kapishche'lerin bir kısmı özgürdür: onları hiçbir klan tutmaz.",
"На святилищах мифологии твоего клана искры и обереги дани — {0}.":"Klanının mitolojisinin tapınaklarında haraçtaki kıvılcım ve tılsımlar {0}.",
