"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"Nav’ın, Olimpos’un, Asgard’ın ve sidhe tepelerinin eski yolları burada buluşur — Moskova’dan Dublin’e.",
"Азия":"Asya",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"Ural Dağları’ndan Büyük Okyanus’a. Çin’in göksel ejderhaları buradan gelir; Sibirya ve Orta Asya ise Slav ruhlarının diyarıdır.",
"Африка":"Afrika",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"Burada, Nil kıyısında, Mısır tanrılarının ve çöl ruhlarının yurdu Duat’ın kapıları durur.",
"Северная Америка":"Kuzey Amerika",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"Tüylü yılanların diyarı: Aztek tanrıları ve ruhları Meksika Vadisi’nden çıktı.",
"Южная Америка":"Güney Amerika",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"Yağmur ormanları, And Dağları ve Amazon. Aztek ruhları buraya da dağıldı — Ateş Toprakları’na kadar.",
"Австралия и Океания":"Avustralya ve Okyanusya",
"Своих мифологий у Ордена здесь пока нет: все духи Австралии и Океании — гости, которых занесла Перепутица.":"Tarikat’ın burada henüz kendi mitolojisi yok: Avustralya ve Okyanusya’daki tüm ruhlar Büyük Düğüm’ün getirdiği misafirler.",
"Антарктида":"Antarktika",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"Burada yalnızca penguenler ve buz ruhları var. Kapılar buraya açılmaz — Avcılar için bile fazla soğuk.",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"Ruhlar dünyası her zaman çoktu, her halkın kendi dünyası vardı: Slavların Nav'ı, Yunanların Hades diyarı, İskandinavların Asgard'ı, Keltlerin peri tepeleri, Mısırlıların Duat'ı, Çinlilerin Gökleri, Azteklerin Mictlan'ı. Onları yerlerinde tutan, bütün dünyaların ortasındaki beyaz yanar taş <b>Alatyr</b>'dı. Her kapı kendi diyarına açılırdı ve ruhlar yollarını hiç karıştırmazdı.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — кто куда. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"Bir sonbahar gecesi Ölümsüz Koschei ölümünü daha güvenli bir yere saklamaya karar verdi: tam Alatyr'ın kalbine. Taş çatladı ve ikiye ayrıldı. Bütün kapılar bir anda açıldı, dünyalar arasındaki yollar yumak gibi birbirine dolandı ve yedi mitolojinin ruhları ile tanrıları dünyamıza dağıldı — her biri bir yana. O geceye <b>Büyük Düğüm</b> dendi. Koschei taşın kendiliğinden çatladığını söylüyor, ama nedense bunu duyunca Loki ile Sun Wukong kıkırdıyor.",
"Теперь Гиппокамп плещется в московском фонтане, Леший гуляет по токийскому парку, а Ниссе греет котов в подъездах Каира. Любого духа можно встретить в любом уголке земли. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища там, где осели: Капище по соседству с Пагодой, Храм через улицу от Пирамиды. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"Artık bir Hippokampus Moskova'daki bir fıskiyede çimiyor, bir Leshy Tokyo'da bir parkta geziniyor, bir Nisse de Kahire'nin apartman merdivenlerinde kedileri ısıtıyor. Her ruh dünyanın her köşesinde karşına çıkabilir. Kırılan taşın bıraktığı çatlaklar olan yarıklar her şehirde açılıyor; tanrılar da nereye yerleştilerse tapınaklarını oraya kuruyor: Pagoda'nın hemen yanında bir Kapishche, Piramit'in karşı kaldırımında bir Tapınak. Şehir kendi yeni ruhlarını da doğuruyor: Vayfayka, Tramvaynik, Fonarnik.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"Misafirlerle ilk anlaşanlar bilim insanları değil, tılsımlarıyla nineler oldu: özenle yapılmış bir tılsımın, nereden gelirse gelsin her ruhu sakinleştirdiği anlaşıldı. <b>Tılsım Tarikatı</b> böyle doğdu: bütün diyarların Avcılarının birliği. Senin görevin: ruhları bulmak, tılsımlarla yakalamak, kaynaklardan güç toplamak, yarıkları kapatmak ve Alatyr parçalarını toplamak. Kim bilir, belki bir gün eve dönen yolları çözmeye yetecek kadar parça birikir.",
