"Быстрота и отвага":"Hız ve cesaret",
"Наследники княжеских дружин под знаком сокола-Рарога. Когда Кощей расколол Алатырь, они первыми встали у Капищ и держат Навь громом Перуна.":"Rarog şahininin işareti altında prens drujinalarının mirasçıları. Koschei Alatyr'ı kırdığında Kapishche'lerin başına ilk onlar geçti ve Nav'ı Perun'un gök gürültüsüyle zapt ediyorlar.",
"Фаланга Олимпа":"Olimpos Falanksı",
"Сова":"Baykuş",
"гоплит":"hoplit",
"Щит к щиту":"Kalkan kalkana",
"Ловчие, что сомкнули щиты под знаком совы Афины. В Перепутицу они стерегут храмы, чтобы тени Аида не вышли к живым.":"Athena'nın baykuşunun işareti altında kalkanlarını birleştiren Avcılar. Büyük Düğüm'de Hades'in gölgeleri yaşayanların arasına çıkmasın diye tapınakları bekliyorlar.",
"Хирд Асгарда":"Asgard Hirdi",
"Волк":"Kurt",
"хирдман":"hirdman",
"Верность и чутьё":"Sadakat ve sezgi",
"Верные, как волки Одина. Хирд стоит у рунных камней, пока не затянутся трещины к Гиннунгагапу.":"Odin'in kurtları kadar sadık. Hird, Ginnungagap'a açılan çatlaklar kapanana dek rün taşlarının başında durur.",
"Братство Дуба":"Meşe Kardeşliği",
"Медведь":"Ayı",
"друид":"druid",
"Сила и стойкость":"Güç ve dayanıklılık",
"Друиды и воины священных рощ под рукой медведицы Артио. Братство держит каменные круги, чтобы холмы сидов не распахнулись навсегда.":"Dişi ayı Artio'nun himayesinde kutsal korulardan druidler ve savaşçılar. Kardeşlik, peri tepeleri sonsuza dek açılmasın diye taş çemberleri tutuyor.",
"Стражи Дуата":"Duat Muhafızları",
"Скарабей":"Skarabe",
"страж":"muhafız",
"Солнце взойдёт снова":"Güneş yine doğacak",
"Хранители солнечной ладьи Ра. Пока Алатырь расколот, стражи стоят у обелисков, чтобы ночь Дуата не поглотила рассвет.":"Ra'nın güneş kayığının bekçileri. Alatyr kırık kaldıkça muhafızlar, Duat'ın gecesi şafağı yutmasın diye dikilitaşların başında durur.",
"Небесная Гвардия":"Göksel Muhafızlar",
"Дракон":"Ejderha",
"гвардеец":"muhafız askeri",
"Небо и земля в равновесии":"Gök ve yer dengede",
"Воины под знаменем Лазурного дракона. В Перепутицу гвардия держит пагоды, чтобы Небесные врата не остались распахнутыми.":"Gök Mavisi Ejderha'nın sancağı altındaki savaşçılar. Büyük Düğüm'de muhafızlar, Göksel Kapılar ardına kadar açık kalmasın diye pagodaları tutar.",
"Орден Ягуара":"Jaguar Tarikatı",
"Ягуар":"Jaguar",
"воин-ягуар":"jaguar savaşçısı",
"Солнце не должно погаснуть":"Güneş sönmemeli",
"Самые отважные воины древних городов Америки. Орден держит пирамиды, чтобы из Миктлана не пришла вечная ночь.":"Amerika'nın kadim şehirlerinin en yürekli savaşçıları. Tarikat, Mictlan'dan sonsuz gece gelmesin diye piramitleri tutar.",
"Клан «{0}»":"“{0}” Klanı",
"воин клана":"klan savaşçısı",
"Вместе — за Алатырь":"Alatyr için birlikte",
"Ловчие мифологии «{0}»: они держат её святилища, пока Алатырь расколот.":"“{0}” mitolojisinin Avcıları: Alatyr kırık kaldıkça onun tapınaklarını tutarlar.",
"Ученик":"Çırak",
"Мастер":"Usta",
"Старейшина":"Ulu",
"Святки":"Svyatki",
"Зимние праздники: Морозко и Снегурка выходят к людям, духи Ветра и Воды встречаются чаще, в источниках — подарки.":"Kış bayramları: Morozko ve Snegurka insanların arasına çıkar, Rüzgâr ve Su ruhları daha sık görülür, kaynaklarda hediyeler var.",
"Масленица":"Maslenitsa",
"Провожаем зиму! Духи Огня встречаются вдвое чаще, в источниках много мёда («блинов»), опыт ×1,5.":"Kışı uğurluyoruz! Ateş ruhları iki kat sık çıkar, kaynaklarda bol bal (“krep”) var, XP ×1,5.",
"Купальская ночь":"Kupala Gecesi",
"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"Eğreltiotu çiçek açtı: Kupalinka her yerde, Ateş, Su ve Orman ruhları daha sık, geceleri parıltılılar iki kat sık.",
"Покров":"Pokrov",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в источниках больше добычи.":"İlk sisler ve kırağı: Rüzgâr ve Su ruhları daha sık çıkar, Listopadnitsa her yerde, kaynaklarda daha çok ganimet var.",
"Велесова ночь":"Veles Gecesi",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"Dünyalar arasındaki sınır en ince hâlinde: Gölge ruhları üç kat sık, büyük yarıklarda Koschei bekliyor, parıltılı Gölgeler iki kat sık.",
"Этот источник теперь принадлежит Нави!":"Bu kaynak artık Nav'ın!",
"Твои духи будут служить Кощею!":"Ruhların Koschei'ye hizmet edecek!",
"Орден Оберега? Никогда о таком не слышал.":"Tılsım Tarikatı mı? Hiç duymadım.",
"Граница рухнет, и мы заберём весь город!":"Sınır çökecek ve bütün şehri alacağız!",
"Думаешь, оберегом меня остановишь?":"Beni bir tılsımla durdurabileceğini mi sanıyorsun?",
"Тьма уже здесь, Ловчий. Смирись.":"Karanlık çoktan burada, Avcı. Kabullen.",
