"Твой прогресс перенесён на другое устройство и продолжается там. На этом устройстве можно начать заново.":"İlerlemen başka bir cihaza aktarıldı ve orada devam ediyor. Bu cihazda baştan başlayabilirsin.",
"Если ты <b>не</b> переносил прогресс — не начинай заново: напиши на почту из «Оферты» (Лавка → Казна) и укажи имя Ловчего и когда это случилось. Прогресс можно вернуть.":"İlerlemeni sen aktarmadıysan baştan <b>başlama</b>: “Sözleşme”deki (Dükkân → Hazine) e-posta adresine yaz, Avcı adını ve bunun ne zaman olduğunu belirt. İlerleme geri getirilebilir.",
"Начать заново":"Baştan başla",
"Перенести прогресс сюда":"İlerlemeyi buraya aktar",
"На старом устройстве открой «Настройки → Перенести на другое устройство» и введи полученный код.":"Eski cihazda “Ayarlar → Başka cihaza aktar”ı aç ve aldığın kodu gir.",
"Текущий прогресс на этом устройстве будет заменён.":"Bu cihazdaki mevcut ilerlemenin yerine geçecek.",
"Вводи только код со своего же устройства. Если код прислал кто-то другой — это может быть обман.":"Yalnızca kendi cihazından aldığın kodu gir. Kodu başka biri gönderdiyse bu bir dolandırıcılık olabilir.",
"Перенести":"Aktar",
