"Прогресс перенесён!":"İlerleme aktarıldı!",
"Код переноса":"Aktarım kodu",
"Введи этот код на новом устройстве: при первом запуске — «У меня уже есть прогресс», или «Настройки → Перенести прогресс сюда». Код действует 30 минут и один раз.":"Bu kodu yeni cihazda gir: ilk açılışta — “Zaten ilerlemem var”, ya da “Ayarlar → İlerlemeyi buraya aktar”. Kod 30 dakika ve tek kullanımlık geçerlidir.",
"После переноса прогресс продолжится на новом устройстве, а здесь можно будет начать заново.":"Aktarımdan sonra ilerleme yeni cihazda devam eder, burada ise baştan başlayabilirsin.",
"<b>Никому не сообщай этот код.</b> По нему забирают весь прогресс — духов, монеты и покупки. Орден, модераторы и друзья никогда не просят код; «подарок за код» — это обман.":"<b>Bu kodu kimseye söyleme.</b> Onunla bütün ilerleme alınır — ruhlar, sikkeler ve satın alımlar. Tarikat, moderatörler ve arkadaşlar asla kod istemez; “kod karşılığı hediye” bir dolandırıcılıktır.",
