"Соперник — Ловчий с рейтингом ±{0} от твоего, а если такого нет — Ловчий Ордена. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"Rakibin, puanı seninkinden en fazla ±{0} farklı bir Avcı; yoksa bir Tarikat Avcısı. Puan rakibin gücüne bağlıdır · günün ilk {1} savaşı için deneyim",
