"от {0}":"{0} puandan itibaren",
"начало пути":"yolun başı",
"Получено в этом сезоне":"Bu sezon alındı",
"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"Puan rakibe bağlıdır: güçlüyü yenmek çok, zayıfı yenmek az kazandırır; zayıfa yenilmek daha pahalıya patlar. Kendi liginde denkini yenmek +{0}, ona yenilmek −{1}; lig yükseldikçe yükseliş yavaşlar. Ligden düşebilirsin. Lig ödülü sezonda bir kez verilir. Yeni sezonun başında {2} üstündeki puan yarıya iner, geçen sezonun en üst ligi için Tarikat bir sandık hediye eder. “{3}”, “{4}” ve “{5}” liglerinde ayrıca muska da var.",
"<b>{0}-е место</b> из {1} в сезоне":"Sezonda {1} kişi içinde <b>{0}. sıra</b>",
"Сыграй бой, чтобы попасть в таблицу":"Tabloya girmek için bir savaş oyna",
"Карточка откроется после обновления сервера":"Kart, sunucu güncellendikten sonra açılacak",
"Неизвестный ход":"Bilinmeyen hamle",
