"Неизвестный приём":"Bilinmeyen özel hamle",
"Этот приём не выучен":"Bu hamle öğrenilmedi",
"Неверный приём":"Geçersiz hamle",
"Этого духа не выпустить":"Bu ruh sahaya sürülemez",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"Tılsımı halka küçülürken at: “Harika!” daha çok XP ve yakalama şansı verir.",
"Источники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"Kaynaklar birkaç dakika sonra yeniden dolar — bir tur yürüyüş erzak getirir.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"Yoldaş seninle yürür ve kendi ailesinin özünü bulur.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"Lig'de gerçek Avcılar savaşır: güçlü rakibi yenmek, zayıfı yenmekten daha çok puan getirir.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"Yarıklar her saat Kapishche'lerin yanında açılır: üç ruhluk bir takım kur.",
"Сияющие духи редки — их выдают искры вокруг.":"Parıltılı ruhlar nadirdir — etraflarındaki kıvılcımlar onları ele verir.",
"Коконы греются шагами: одновременно можно греть три.":"Kozalar adımlarla ısınır: aynı anda üç koza ısıtabilirsin.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"Joystick ile yürü: hafif eğim yürüme, sonuna kadar koşma. Kilometreler kozalar için aynen sayılır.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"Dünya Atlası seni yarım saatte bir Dünya’nın herhangi bir köşesine götürür, Büyük Düğüm Kapıları ise hemen.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"Günün görevleri gece yarısı yenilenir, üçünü de bitirince Günün Sandığı seni bekler.",
"Поставь защитника на Капище своего клана — он принесёт искры.":"Klanının Kapishche'sine savunucu koy — sana kıvılcım getirir.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"Hava kendi elementindeki ruhları güçlendirir: yağmurda su ruhları daha sık çıkar.",
"Привяжи вход через Google, Яндекс или Telegram — прогресс не потеряется при смене телефона.":"Google, Yandex ya da Telegram ile giriş bağla — telefon değiştirince ilerleme kaybolmaz.",
"Дари друзьям подарки каждый день — дружба растёт и приносит опыт.":"Arkadaşlarına her gün hediye ver — dostluk büyür ve XP getirir.",
