"У того Ловчего есть и другие способы входа — его прогресс останется доступен через них.":"O Avcının başka giriş yolları var — ilerlemesine onlarla ulaşılabilir.",
"<b>У того Ловчего не останется других способов входа — его прогресс станет недоступен навсегда.</b>":"<b>O Avcının başka giriş yolu kalmayacak — ilerlemesi sonsuza dek kaybolacak.</b>",
