"Прогресс останется в учётной записи — вернуться в неё можно тем же входом. На этом устройстве начнётся новая гостевая игра.":"İlerleme hesapta kalır — aynı girişle ona geri dönebilirsin. Bu cihazda yeni bir misafir oyunu başlar.",
"Выйти":"Çık",
