"Заходи каждый день — награды растут, а на 7-й день ждёт кокон 10 км.":"Her gün uğra — ödüller büyür, 7. günde de 10 km'lik bir koza bekliyor.",
"Седьмой день! Завтра круг начнётся снова — серия продолжается.":"Yedinci gün! Yarın döngü yeniden başlar — seri devam ediyor.",
